content:
return CLAUSE_NONE;
                }
        }

        if (stressed_word)
                ix += utf8_out(CHAR_EMPHASIS, &buf[ix]);
        if (end_clause_after_tag)
                RemoveChar(&buf[end_clause_index]); // delete clause-end punctiation
        buf[ix] = ' ';
        buf[ix+1] = 0;
        return CLAUSE_EOF; // end of file
}

void InitNamedata(void)
{
        namedata_ix = 0;
        if (namedata != NULL) {
                free(namedata);
                namedata = NULL;
                n_namedata = 0;
        }
}

